"""The Guild Hall's own navmesh (generated by
us, the CK's Recast as the fallback). From an exported interior (guildhall_gen AG_EXPORT JSON): its collision as a 2.5D
heightfield, every walkable surface found on it, eroded by an actor's radius, meshed, written as JSON for Hall2.cs, which
writes the NAVM and its NAVI entry (conventions measured from vanilla's: HallSpike's `navdump`).

  1. Columns every G (8) in the hall's frame. Each near-level collision face gives a surface at its height in the columns
     whose centres it covers; every face, of any slope, blocks the heights it spans in the columns it touches (steep ones
     along their footprint's edges). A surface is walkable if nothing blocks from 6 to HEAD (120) over it.
  2. The vanilla pieces block too: their measured footprints (furniture_check.py's), HEIGHT tall, at their floor. Doors
     do not (actors open them); load doors do not.
  3. Walkable surfaces in neighbouring columns join if they differ by up to STEP (26: the spiral stair's risers are 16).
     Each joined set touching an exterior column (a missing neighbour) is eroded by R (16) through the joins. Sets
     smaller than MIN_AREA are dropped (wall tops, sills).
  4. As Recast meshes: flat regions (a floor at its height, the dais, each stair tread) outlined on the columns' edges,
     each outline between two regions (or a region and the wall) simplified once (Douglas-Peucker, TOL) and shared by
     both sides, so the regions still join; each region's polygon, its holes bridged in, ear-clipped. (A first try, a
     quadtree of 16-unit cells, gave 14,900 triangles; vanilla's cells of this size have 300-900, the CK warns at 5,000.)
     Then Delaunay flips only, no points added (2026-11-11, the rebuild: vanilla's and hand-made mods' meshes have their
     vertices on the border, ~1.2 triangles per 100x100, no shared edge under 10); a stair a ramp one quad across.
  5. Adjacency from shared edges; door triangles under each load door's landing point; the NAVM's search grid.

    python navgen.py <hall2_*.json> <out.json> [--plot out.png] [--doors doors.json] [--records records.json]
"""
import re, sys, os, json, math
from collections import defaultdict
import numpy as np
from scipy import ndimage

args = sys.argv[1:]
def sopt(k):
    if k in args: i = args.index(k); v = args[i + 1]; del args[i:i + 2]; return v
    return None
PLOT = sopt("--plot")
RECORDS = sopt("--records")
src, out = args[0], args[1]
G, B, HEAD, STEP, R, MIN_AREA, HEIGHT = 8.0, 16.0, 120.0, 26.0, float(os.environ.get("NAV_R", 8.0)), 60, 90.0
# (the SE test install's run: NPCs stopping on the way, then teleporting, which is the engine's warp after three path
# failures running: iWarpMaxPathFailureCount and bWarpOnConsecutiveFailures, read from the game. The engine keeps an actor's own radius
# off a navmesh's edge, fNavmeshBoundsActorRadiusMultiplier 1.0, and this mesh had been eroded by a radius first: a way an actor fits
# through 40 wide came out a strip 8 wide; vanilla's navmesh across its inner doors measures 76 / 90 / 112 at 5 / 25 / 50% (navdoorw),
# ours 48-70.) So two distances: a way counts if an actor's disc of CORE fits along it; the mesh then runs out to R from what blocks it
CORE = float(os.environ.get("NAV_CORE", 24.0))
D = json.load(open(src))
H = lambda p: (p[1], -p[0], p[2])                    # layout -> hall
Lf = lambda p: (-p[1], p[0], p[2])                   # hall -> layout (the cell's own frame)
T = np.array([[H(p) for p in t] for t in D["coll"]], float)

# the pieces' footprints: furniture_check.py's measured table (its FP / EXTRA / BYMODEL definitions, read from its source)
fc = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "furniture_check.py"), encoding="utf-8").read()
ns = {}
exec(fc[fc.index("FP = {"):fc.index("def rot(yaw):")], ns)
FP, EXTRA = ns["FP"], ns["EXTRA"]

x0, y0 = T[:, :, 0].min() - 2 * G, T[:, :, 1].min() - 2 * G
x1, y1 = T[:, :, 0].max() + 2 * G, T[:, :, 1].max() + 2 * G
NX, NY = int((x1 - x0) / G) + 1, int((y1 - y0) / G) + 1
print(f"NAVGEN {os.path.basename(src)}: {len(T)} collision faces, columns {NX} x {NY}")
surf = defaultdict(list)                              # (i, j) -> [z]
block = defaultdict(list)                             # (i, j) -> [(z0, z1)]
nrm = np.cross(T[:, 1] - T[:, 0], T[:, 2] - T[:, 0]); nl = np.linalg.norm(nrm, axis=1) + 1e-9; NZ = np.abs(nrm[:, 2]) / nl
for t, nz in zip(T, NZ):
    xs, ys, zs = t[:, 0], t[:, 1], t[:, 2]
    i0, i1 = int((xs.min() - x0) / G), int((xs.max() - x0) / G) + 1
    j0, j1 = int((ys.min() - y0) / G), int((ys.max() - y0) / G) + 1
    if nz > 0.25:                                       # covered column centres, the face's height there
        ii, jj = np.meshgrid(np.arange(i0, i1 + 1), np.arange(j0, j1 + 1))
        px, py = x0 + (ii + 0.5) * G, y0 + (jj + 0.5) * G
        a, b, c = t
        d = (b[1] - c[1]) * (a[0] - c[0]) + (c[0] - b[0]) * (a[1] - c[1])
        if abs(d) > 1e-9:
            l1 = ((b[1] - c[1]) * (px - c[0]) + (c[0] - b[0]) * (py - c[1])) / d
            l2 = ((c[1] - a[1]) * (px - c[0]) + (a[0] - c[0]) * (py - c[1])) / d
            l3 = 1 - l1 - l2
            inside = (l1 >= -1e-6) & (l2 >= -1e-6) & (l3 >= -1e-6)
            zz = l1 * a[2] + l2 * b[2] + l3 * c[2]
            hh = 1.0 if nz > 0.7 else 0.5 * G * math.sqrt(max(0.0, 1 - nz * nz)) / nz + 1   # (a slope's rise across a column)
            for i, j, z in zip(ii[inside], jj[inside], zz[inside]):
                if nz > 0.7: surf[(i, j)].append(float(z))
                block[(i, j)].append((float(z) - hh, float(z) + hh))
    if nz < 0.25:                                       # a wall: the heights it occupies in each column it passes through,
        a, b, c = t                                     # sampled over its face (a rafter's side runs from the eave up to
        L_ = max(np.linalg.norm(b - a), np.linalg.norm(c - a), np.linalg.norm(c - b))   # the ridge: only its low end blocks low)
        n_ = max(2, int(L_ / (G / 3)) + 1)
        u_, v_ = np.meshgrid(np.linspace(0, 1, n_), np.linspace(0, 1, n_)); m_ = (u_ + v_) <= 1.0001
        u_, v_ = u_[m_], v_[m_]
        P_ = a[None, :] + u_[:, None] * (b - a)[None, :] + v_[:, None] * (c - a)[None, :]
        ci_ = ((P_[:, 0] - x0) / G).astype(int); cj_ = ((P_[:, 1] - y0) / G).astype(int)
        key_ = ci_ * 100000 + cj_
        order_ = np.argsort(key_, kind="stable"); ks_ = key_[order_]; zs_ = P_[order_, 2]
        cuts_ = np.flatnonzero(np.diff(ks_)) + 1
        for grp_ in np.split(np.arange(len(ks_)), cuts_):
            k0_ = int(ks_[grp_[0]]); zg_ = zs_[grp_]
            block[(k0_ // 100000, k0_ % 100000)].append((float(zg_.min()) - 1, float(zg_.max()) + 1))

def rot(yaw):
    a = math.radians(yaw); return (math.cos(a), -math.sin(a)), (math.sin(a), math.cos(a))
# (2026-11-04: a piece not in that table was skipped, so the navmesh ran under the basement's tables, targets, dummies, workbench and
# casks, and an actor put on it stands inside the piece; Henriette was found standing on the dining table. A piece the table does not
# name now blocks by its record's bounds, records.json (--records; gates_export.sh writes it beside the export), at their own heights, so what
# hangs above head height blocks nothing; doors (actors open them) and items lying about (walked over) do not. The table's own None
# entries (rugs) stay as they are.)
# (given by --records: build_hall.sh's early pass, for the rooms only, runs while gates_export.sh is still writing that file; a
# --records file that is missing or unreadable fails, never a navmesh built without it)
REC = json.load(open(RECORDS)) if RECORDS else None
# and each piece big enough to stand on (a table) blocks PAD further out than its footprint on its unused sides (2026-11-04): with the mesh's own R that keeps the
# navmesh an actor's radius (14, nav_routes' 28 thick) and more from it there, so an actor stood on the edge never overlaps it
PAD = float(os.environ.get("NAV_PAD", 12.0))
NOBLOCK_T = {"Door", "Weapon", "Ammunition", "MiscItem", "Book", "Flora", "Ingestible", "Ingredient", "Key", "SoulGem", "Scroll", "Armor", "Light"}
NOBLOCK_M = re.compile(r"(?i)^meshes[\\/]effects[\\/]")    # (effects: glows, fog, light shafts; no collision in game)
npieces = nrec = 0; unknown_ = []
for p in D["pieces"]:
    ed = p.get("ed") or os.path.basename(p["model"])
    x, y, z = H(p["pos"]); ex, ey = rot(p["yaw"] + 90); s_ = p.get("scale", 1.0)
    if ed in FP:
        fp = FP[ed]
        if not fp or not fp[0]: continue
        boxes_ = [fp[0]] + EXTRA.get(ed, []); zr_ = (z + 2, z + HEIGHT); npieces += 1
    else:
        r_ = (REC or {}).get(ed)
        if r_ is None:
            if REC is not None: unknown_.append(ed)
            continue
        if r_.get("type") in NOBLOCK_T or (r_.get("type") == "Activator" and "Water" in ed): continue
        if NOBLOCK_M.match(p["model"]): continue   # (2026-11-05: an effect, a window's glow card 353 across, has no collision; it cut the rooms' navmesh)
        bx0, by0, bz0, bx1, by1, bz1 = r_["obnd"]
        if bz1 - bz0 < 6 or bx1 <= bx0 or by1 <= by0: continue
        boxes_ = [(bx0, by0, bx1, by1)]; zr_ = (z + bz0 * s_ + 2, z + bz1 * s_); nrec += 1
    for (a0, b0, a1, b1) in boxes_:
        # (only the sides no one uses: a side with an entry point beyond it, a bed's or a bench's, keeps the mesh's own R, so the
        # strip beside a bunk stays; the dining table's ends, the one Henriette was found over, get the whole margin)
        ents_ = (FP.get(ed) or (None, []))[1] if ed in FP else []
        if min(a1 - a0, b1 - b0) * s_ < 70: ents_ = [(-1e9, 0), (1e9, 0), (0, -1e9), (0, 1e9)]   # (too small to stand on, a nightstand
                                                                                                # or a chest by a bed: no margin, the bedside strip stays)
        pa0 = 0 if any(ex_ < a0 for ex_, _ in ents_) else PAD; pa1 = 0 if any(ex_ > a1 for ex_, _ in ents_) else PAD
        pb0 = 0 if any(ey_ < b0 for _, ey_ in ents_) else PAD; pb1 = 0 if any(ey_ > b1 for _, ey_ in ents_) else PAD
        a0, b0, a1, b1 = a0 - pa0 / s_, b0 - pb0 / s_, a1 + pa1 / s_, b1 + pb1 / s_
        for la in np.arange(a0, a1 + G / 2, G / 2):
            for lb in np.arange(b0, b1 + G / 2, G / 2):
                wx, wy = x + (la * ex[0] + lb * ey[0]) * s_, y + (la * ex[1] + lb * ey[1]) * s_
                block[(int((wx - x0) / G), int((wy - y0) / G))].append(zr_)
print(f"  {npieces} pieces block their footprints, {nrec} their record's bounds" + ("" if REC is not None else " (no --records: only the table's pieces block)"))
unknown_ = sorted(set(u for u in unknown_ if u))
if unknown_: print(f"  (pieces with neither a footprint nor a record, blocking nothing: {', '.join(unknown_)})")

# walkable surfaces: (i, j, z)
spans = {}                                            # (i, j) -> sorted list of walkable z
for (i, j), zs in surf.items():
    zs = sorted(zs); keep = []
    for z in zs:
        if keep and z - keep[-1] < 8: keep[-1] = max(keep[-1], z); continue   # (a slab's underside, 4 under its top: one floor)
        keep.append(z)
    bl = block.get((i, j), [])
    ok = []
    for z in keep:
        hit = [(b0, b1) for b0, b1 in bl if b0 < z + HEAD and b1 > z + 6]
        if not hit: ok.append(z); continue
        top = max(b1 for b0, b1 in hit)                # (a step's edge in this column: what rises no more than a step over
        if top <= z + STEP and not any(b0 < top + HEAD and b1 > top + 6 for b0, b1 in bl):   # the surface is stood on, at
            ok.append(top)                             # its top, as Recast's climb allows)
    ok2 = []
    for z in sorted(set(round(z, 2) for z in ok)):         # (one surface within 8: a rail's or a step's top over the floor)
        if ok2 and z - ok2[-1] < 8: ok2[-1] = max(ok2[-1], z); continue
        ok2.append(z)
    if ok2: spans[(i, j)] = ok2
nodes = [(i, j, z) for (i, j), zs in spans.items() for z in zs]
idx = {n: k for k, n in enumerate(nodes)}
def nbrs(n):
    i, j, z = n
    for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        for z2 in spans.get((i + di, j + dj), ()):
            if abs(z2 - z) <= STEP: yield (i + di, j + dj, z2)
# erosion by R through the joins: distance (in columns) from an edge node (fewer than four joined neighbours)
from collections import deque
dist = {}; q = deque()
for n in nodes:
    k_ = sum(1 for _ in nbrs(n))
    if k_ < 4: dist[n] = 0; q.append(n)
while q:
    n = q.popleft()
    for m in nbrs(n):
        if m not in dist: dist[m] = dist[n] + 1; q.append(m)
RC, RCORE = int(math.ceil(R / G)), int(math.ceil(CORE / G))
walk = {n for n in nodes if dist.get(n, 99) >= RCORE}
# (the first try at this lost a bunk: the aisle to it is 48 wide) a way narrower than CORE but wide enough to squeeze along stays if it is
# what reaches somewhere; left out only if it is a shortcut, touching the wider ways at two places or more, so no one is sent through it
tight_ = {n for n in nodes if dist.get(n, 99) >= RC + 1 and n not in walk}
wide_ = walk | {m for n in walk for m in nbrs(n) if m in tight_}
seen_ = set(); dropped_ = 0; kept_ = 0
for n0_ in sorted(tight_ - wide_):
    if n0_ in seen_: continue
    part_ = {n0_}; st_ = [n0_]
    while st_:
        for m in nbrs(st_.pop()):
            if m in tight_ and m not in wide_ and m not in part_: part_.add(m); st_.append(m)
    seen_ |= part_
    mouth_ = {m for n in part_ for m in nbrs(n) if m in wide_}; groups_ = 0; left_ = set(mouth_)
    while left_:
        groups_ += 1; st_ = [left_.pop()]
        while st_:
            for m in nbrs(st_.pop()):
                if m in left_: left_.discard(m); st_.append(m)
    if groups_ >= 2: dropped_ += 1
    else: walk |= part_; kept_ += 1
walk |= wide_
print(f"  tight ways: {kept_} kept (they reach somewhere), {dropped_} shortcuts left out")
grow_ = set(walk)
for _ in range(RCORE - RC):                           # (out from the ways an actor fits along, to R from what blocks them)
    next_ = {m for n in grow_ for m in nbrs(n) if m not in walk and dist.get(m, 99) >= RC}
    walk |= next_; grow_ = next_
# joined sets; small ones dropped
comp = {}; sets = []
for n in walk:
    if n in comp: continue
    c_ = len(sets); comp[n] = c_; st = [n]; mem = [n]
    while st:
        a_ = st.pop()
        for m in nbrs(a_):
            if m in walk and m not in comp: comp[m] = c_; st.append(m); mem.append(m)
    sets.append(mem)
# kept: the sets an actor can reach, those under a load door's landing (front, patio, ladders, the hatch), the rest
# (the tower's ceiling, the chimneys' tops) are islands no one stands on
anchors = []
ROLE_NAME_ = {"ladder": "AGHall2LadderDoor"}
for p_ in D["pieces"]:
    if p_.get("arrive"): anchors.append(H(p_["arrive"]))
if "patio_land" in D: anchors.append(H(D["patio_land"][0] if isinstance(D["patio_land"][0], list) else D["patio_land"]))
if "patio_land" in D: anchors.append(H([-132, 0, 0]))
if not anchors and D.get("pieces"): anchors = [H(p_["pos"]) for p_ in D["pieces"] if p_.get("role") == "hatch"]
reach_sets = set()
colsets = defaultdict(list)
for n in walk: colsets[(n[0], n[1])].append(n)
for ax, ay, az in anchors:
    ci, cj = int((ax - x0) / G), int((ay - y0) / G); best = None
    for di in range(-8, 9):
        for dj in range(-8, 9):
            for n in colsets.get((ci + di, cj + dj), ()):
                d_ = abs(di) + abs(dj) + abs(n[2] - az) / 8
                if best is None or d_ < best[0]: best = (d_, comp[n])
    if best: reach_sets.add(best[1])
big = {k for k in reach_sets if len(sets[k]) >= MIN_AREA} if reach_sets else {k for k, m in enumerate(sets) if len(m) >= MIN_AREA}
walk = {n for n in walk if comp[n] in big}
print(f"  {len(nodes)} surfaces, {len(walk)} walkable after erosion ({R}), {len(big)} sets kept of {len(sets)}")
wz = defaultdict(list)
for (i, j, z) in walk: wz[(i, j)].append(z)

def at(x, y, zref):
    """the walkable surface at a point nearest zref (within STEP), or None"""
    k_ = (int((x - x0) / G), int((y - y0) / G))
    best = None
    for z in wz.get(k_, ()):
        if abs(z - zref) <= STEP and (best is None or abs(z - zref) < abs(best - zref)): best = z
    return best

# the mesh, as Recast makes one: flat regions (each floor at its height, the dais, each stair tread), their outlines
# traced on the columns' edges, the outline between two regions (or a region and the wall) simplified once and shared by
# both, each region's polygon (with its holes) ear-clipped. Vertices only on outlines: few, long triangles, as vanilla's.
nodes_w = sorted(walk)
# (a follower could not go up the stairs) the spiral stair as vanilla meshes
# one (HallSpike's stairnav, the Blue Palace's and Fort Dawnguard's spirals: 82-122 triangles over a whole stair, their
# inradius 20-25, none under 4, slopes 2-16 degrees: a ramp along the walking line, not a region per tread; ours had 814
# triangles there, 753 of them slivers, 117 steeper than 45 degrees). Each flight's treads (its landing stays a floor) are
# taken out of the heightfield here and laid as a ramp of quads below, from the surface it leaves to the one it reaches,
# its two ends stitched into the outlines the heightfield leaves there
RAMPS = []; CUT_COLS = defaultdict(list)            # (the tread columns taken out, by column: their heights)
if D.get("stair"):
    ST_ = D["stair"]; SCX, SCY = ST_["centre"]
    for i0_, n_, landing_ in ST_["flights"]:
        fl_ = ST_["steps"][i0_:i0_ + n_]; tre_ = fl_[:-1] if landing_ else fl_; h_ = fl_[0][3]
        RAMPS.append({"a": [t_[0] for t_ in tre_] + [tre_[-1][1]], "z_s": fl_[0][2] - h_,
                      "z_e": fl_[-1][2] if landing_ else fl_[-1][2] + h_, "h": h_, "cut": []})
    def ramp_z(rp, a):
        return rp["z_s"] + (rp["z_e"] - rp["z_s"]) * (a - rp["a"][0]) / (rp["a"][-1] - rp["a"][0])
    def on_ramp(n):
        x_, y_ = x0 + (n[0] + 0.5) * G, y0 + (n[1] + 0.5) * G
        r_ = math.hypot(x_ - SCX, y_ - SCY); th_ = math.degrees(math.atan2(y_ - SCY, x_ - SCX)) % 360
        # (W's treads are square, out to the tower's walls in its corners: a column is a tread's if it lies in the treads'
        # outline at its height; without one, within the steps' ends and a column)
        rect_ = next((rc_ for zc_, rc_ in ST_.get("rects", []) if n[2] < zc_ - 1), None)
        if rect_ is not None:
            if not (rect_[0] - G <= x_ <= rect_[2] + G and rect_[1] - G <= y_ <= rect_[3] + G): return None
        elif r_ > ST_["r"][1] + 1.5 * G: return None
        for k_, rp in enumerate(RAMPS):
            lo_, hi_ = min(rp["a"][0], rp["a"][-1]), max(rp["a"][0], rp["a"][-1])
            zlo_, zhi_ = min(rp["z_s"], rp["z_e"]), max(rp["z_s"], rp["z_e"])
            for w_ in range(-4, 5):
                a_ = th_ + 360 * w_
                # (a tread's by its height, not its angle: between the floor it leaves and the one it reaches by more than
                # half a riser, and near the ramp's height there; within 3 degrees past either end too, so no scrap of the
                # first or last tread is left in the floor to break its edge into short pieces, where actors would never take a step)
                if lo_ - 3 < a_ < hi_ + 3 and zlo_ + abs(rp["h"]) / 2 < n[2] < zhi_ - abs(rp["h"]) / 2                         and abs(n[2] - ramp_z(rp, min(hi_, max(lo_, a_)))) <= abs(rp["h"]) + 6: return k_, r_
        return None
    keep_ = []
    for n in nodes_w:
        hit_ = on_ramp(n)
        if hit_: RAMPS[hit_[0]]["cut"].append(hit_[1]); CUT_COLS[(n[0], n[1])].append(n[2])
        else: keep_.append(n)
    nodes_w = keep_
    wz = defaultdict(list)                            # (the regions' joins read the surfaces from wz: the treads leave it too)
    for (i, j, z) in nodes_w: wz[(i, j)].append(z)
    for rp in RAMPS: print(f"  ramp {rp['a'][0]:.0f}..{rp['a'][-1]:.0f} deg, z {rp['z_s']:.0f}..{rp['z_e']:.0f}: {len(rp['cut'])} tread columns taken out")
def joined(n):
    i, j, z = n
    for d, (di, dj) in enumerate(((1, 0), (0, 1), (-1, 0), (0, -1))):
        hit = None
        for z2 in wz.get((i + di, j + dj), ()):
            if abs(z2 - z) <= STEP and (hit is None or abs(z2 - z) < abs(hit - z)): hit = z2
        yield d, (None if hit is None else (i + di, j + dj, hit))
REGION_DZ = float(os.environ.get("NAV_DZ", 2.5))     # (a floor 1 off its neighbour, 0 and 1 across the ground floor, is one floor: an outline between them buys nothing)
reg = {}; regz = []
for n in nodes_w:
    if n in reg: continue
    r_ = len(regz); reg[n] = r_; regz.append(n[2]); st = [n]
    while st:
        a_ = st.pop()
        for d, m in joined(a_):
            if m is not None and m not in reg and abs(m[2] - a_[2]) < REGION_DZ: reg[m] = r_; st.append(m)
# (a stair's treads, sampled every 8, leave slivers of a column or three at their edges, each at its own height: each
# is absorbed by the neighbouring region nearest its height, so the stair is a run of treads, not hundreds of slivers)
# (2026-11-11, the navmesh rebuild: scraps up to 40 columns, not 3. The top treads of the basement stair left strips of 5-20 columns at
# -1..-5, each its own region with its own outline: a zig-zag of short edges where the ramp met the ground floor)
ABSORB = int(os.environ.get("NAV_ABSORB", 40))
for _ in range(40):
    size_ = defaultdict(int)
    for n_, r_ in reg.items(): size_[r_] += 1
    moved = 0
    for n_ in nodes_w:
        r_ = reg[n_]
        if size_[r_] > ABSORB: continue
        best = None
        for d, m in joined(n_):
            if m is not None and m in reg and reg[m] != r_ and size_[reg[m]] > ABSORB:
                dz_ = abs(m[2] - n_[2])
                if best is None or dz_ < best[0]: best = (dz_, reg[m])
